fix:
Keep database transactions short by preparing all data and performing external network calls before opening the transaction.
```rust
fn handle_checkout(db: &Database, cart_id: u64) -> Result<(), Error> {
    let cart = db.get_cart_read_only(cart_id)?;
    let payment_success = http::call_stripe_api(cart.total)?; // Done outside transaction

    if payment_success {
        let mut tx = db.begin_transaction()?;
        tx.mark_as_paid(cart_id)?; // Database write is short and fast
        tx.commit()?;
    }
    Ok(())
}
```
